public class ArchiveReviewChecks {
    static int checks;
    static void check(String label,boolean ok){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
    static void reject(String label,int code,Runnable action){try{action.run();throw new AssertionError(label);}catch(EhrException error){check(label,error.status==code);}}
    static OcrRosterIdentityChecks.Fixture fixture(EhrRepository db,EhrService ehr,EhrActor actor,boolean complete){OcrRosterIdentityChecks.Fixture f=OcrRosterIdentityChecks.fixture(db,ehr,actor,"1980-12-31","backend_file");Map<String,Object> report=ehr.report(actor,f.report,1,false);ehr.saveDraft(actor,f.report,1,map("fullName","原姓名","examDate","2026-01-01","institution","隔离审核测试机构","metadataPage",1,"conclusionPage",1,"formalConclusion",complete?"隔离测试报告结论":"","advice","隔离测试建议","items",Arrays.asList(map("name","隔离指标","value","8.2","unit","mmol/L","referenceRange","3.9-6.1","abnormal","H","page",1,"itemCode",""))),str(report.get("etag")));return f;}
    static Map<String,Object> request(EhrService ehr,EhrActor actor,String report,String action){return map("action",action,"requestKey",id(),"note","已核对隔离测试原件与身份，仅验证流程，不用于实际诊疗","etag",ehr.report(actor,report,1,false).get("etag"),"identityVerified",true,"contentVerified",true,"conflictsResolved",true);}
    @SuppressWarnings("unchecked") public static void main(String[] args){
        if(!System.getenv("EHR_JDBC_URL").contains("/shayu_3_preview?"))throw new IllegalArgumentException("Isolated preview database required");DriverManagerDataSource source=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(source);EhrService ehr=new EhrService(db);ReportMatchingService matching=new ReportMatchingService(db,ehr);ArchiveReviewService service=new ArchiveReviewService(db,ehr,matching);EhrActor actor=new EhrActor("review-fixture","REVIEW_"+id().substring(0,8),"synthetic",true,false),reader=new EhrActor("review-reader",actor.scope.substring(4),"synthetic",false,false);DataSourceTransactionManager manager=new DataSourceTransactionManager(source);
        new TransactionTemplate(manager).execute(tx->{try{
            OcrRosterIdentityChecks.Fixture f=fixture(db,ehr,actor,true);Map<String,Object> beforeProfile=ehr.profile(actor,f.record,false),draft=service.detail(actor,f.report,1);
            check("draft_not_falsely_pending_or_approved","draft".equals(draft.get("reviewState")));
            check("scoped_list_has_current_report",num(service.list(actor,new HashMap<>()).get("total"))==1);
            check("detail_includes_real_items_and_versions",((List<?>)((Map<?,?>)draft.get("report")).get("items")).size()==1&&((List<?>)draft.get("versions")).size()==1);
            Map<String,Object> approve=request(ehr,actor,f.report,"approve");reject("non_doctor_cannot_approve",403,()->service.act(reader,f.report,1,approve));
            Map<String,Object> noProof=new LinkedHashMap<>(approve);noProof.put("contentVerified",false);reject("all_three_confirmations_required",422,()->service.act(actor,f.report,1,noProof));
            Map<String,Object> stale=new LinkedHashMap<>(approve);stale.put("etag","stale");reject("stale_review_snapshot_rejected",409,()->service.act(actor,f.report,1,stale));
            Map<String,Object> noNote=new LinkedHashMap<>(approve);noNote.put("note","");reject("review_note_required",422,()->service.act(actor,f.report,1,noNote));
            String originalFields=str(ehr.rawReport(actor,f.report,1,false).get("field_values"));List<Map<String,Object>> conflict=(List<Map<String,Object>>)ehr.decode(originalFields);for(Map<String,Object> field:conflict)if("full_name".equals(field.get("field_key")))field.put("value_raw","不属于关联职工的姓名");db.exec("UPDATE a_health_reports SET field_values=? WHERE report_id=?",ehr.encode(conflict),f.report);Map<String,Object> nameConflict=request(ehr,actor,f.report,"approve_archive");reject("reported_name_conflict_blocks_review",422,()->service.act(actor,f.report,1,nameConflict));
            db.exec("UPDATE a_health_reports SET field_values=? WHERE report_id=?",originalFields,f.report);conflict=(List<Map<String,Object>>)ehr.decode(originalFields);conflict.add(map("field_key","employee_number","value_raw","WRONG_CODE"));db.exec("UPDATE a_health_reports SET field_values=? WHERE report_id=?",ehr.encode(conflict),f.report);Map<String,Object> codeConflict=request(ehr,actor,f.report,"approve_archive");reject("reported_employee_code_conflict_blocks_review",422,()->service.act(actor,f.report,1,codeConflict));db.exec("UPDATE a_health_reports SET field_values=? WHERE report_id=?",originalFields,f.report);
            ehr.candidateOnly=true;reject("candidate_only_environment_respected",403,()->service.act(actor,f.report,1,approve));ehr.candidateOnly=false;
            Map<String,Object> ready=service.act(actor,f.report,1,approve);check("approval_preserves_ready_to_archive_stage","ready".equals(ready.get("reviewState"))&&db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f.report)==0);
            service.act(actor,f.report,1,approve);check("approve_receipt_replay_idempotent",db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=? AND decision='confirm'",f.report)==1);
            Map<String,Object> changed=new LinkedHashMap<>(approve);changed.put("note","不同请求内容");reject("receipt_key_reuse_for_changed_payload_denied",409,()->service.act(actor,f.report,1,changed));
            Map<String,Object> archived=service.act(actor,f.report,1,request(ehr,actor,f.report,"archive"));check("archive_requires_and_uses_doctor_snapshot","archived".equals(archived.get("reviewState"))&&db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f.report)==1);
            check("roster_unchanged_after_review_and_archive",ehr.encode(beforeProfile).equals(ehr.encode(ehr.profile(actor,f.record,false))));
            check("original_file_and_items_retained",db.count("SELECT COUNT(*) FROM a_report_revision_sources WHERE report_id=? AND revision=1",f.report)==1&&"8.2".equals(db.one("SELECT result_raw FROM a_health_items WHERE report_id=? AND revision=1",f.report).get("result_raw")));
            reject("archived_report_cannot_be_returned",409,()->service.act(actor,f.report,1,request(ehr,actor,f.report,"return")));
            OcrRosterIdentityChecks.Fixture f2=fixture(db,ehr,actor,true);Map<String,Object> composite=request(ehr,actor,f2.report,"approve_archive");service.act(actor,f2.report,1,composite);check("explicit_combined_action_approves_and_archives",db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f2.report)==1&&db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=? AND decision='confirm'",f2.report)==1);
            service.act(actor,f2.report,1,composite);check("combined_action_replay_does_not_publish_twice",db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f2.report)==1);
            OcrRosterIdentityChecks.Fixture returned=fixture(db,ehr,actor,true);String old=ehr.encode(ehr.snapshot(returned.report,1));Map<String,Object> returnRequest=request(ehr,actor,returned.report,"return"),newVersion=service.act(actor,returned.report,1,returnRequest);check("return_creates_new_revision",num(((Map<?,?>)newVersion.get("report")).get("revision"))==2&&"returned".equals(newVersion.get("reviewState")));
            check("returned_original_revision_snapshot_retained",old.equals(ehr.encode(ehr.snapshot(returned.report,1)))&&db.count("SELECT COUNT(*) FROM a_report_revision_sources WHERE report_id=?",returned.report)==2);
            service.act(actor,returned.report,1,returnRequest);check("return_receipt_replay_does_not_create_extra_versions",db.count("SELECT COUNT(*) FROM a_health_reports WHERE report_id=?",returned.report)==2);
            OcrRosterIdentityChecks.Fixture good=fixture(db,ehr,actor,true),bad=fixture(db,ehr,actor,false);String before=ehr.encode(ehr.snapshot(good.report,1));Map<String,Object> goodRequest=request(ehr,actor,good.report,"approve_archive"),badRequest=request(ehr,actor,bad.report,"approve_archive");goodRequest.put("reportId",good.report);goodRequest.put("revision",1);badRequest.put("reportId",bad.report);badRequest.put("revision",1);Map<String,Object> batch=map("action","approve_archive","items",Arrays.asList(goodRequest,badRequest));TransactionTemplate nested=new TransactionTemplate(manager);nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
            reject("incomplete_batch_rejected",422,()->nested.execute(inner->{service.batch(actor,batch);return null;}));
            check("failed_batch_rolls_back_all_publications",db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id IN (?,?)",good.report,bad.report)==0&&db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=?",good.report)==0&&before.equals(ehr.encode(ehr.snapshot(good.report,1))));
            reject("cross_org_review_detail_denied",404,()->service.detail(new EhrActor("other","OTHER_REVIEW","synthetic",true,false),f.report,1));
            reject("mobile_review_list_denied",403,()->service.list(new EhrActor("mobile",actor.scope.substring(4),"synthetic",false,true),new HashMap<>()));
            Map<String,String> q=new HashMap<>();q.put("status","invalid");reject("invalid_review_filter_rejected",422,()->service.list(actor,q));q.clear();q.put("search","%' OR 1=1 --");check("review_search_not_sql_injectable",num(service.list(actor,q).get("total"))==0);
            check("review_events_record_explicit_confirmations",str(db.one("SELECT redacted_diff FROM a_health_archive_audit_logs WHERE report_id=? AND action='review_center_approve_archive'",f2.report).get("redacted_diff")).contains("contentVerified"));
            return null;
        }finally{tx.setRollbackOnly();}});System.out.println("PASS archive review checks: "+checks+"; all fixtures and publication events rolled back, no external requests");
    }
}
